// Test-only, synthetic contract fixtures. Expected values are literal oracles,
// not snapshots generated by the production functions being tested.
// These are NOT accountant-certified tax-amount golden cases.
export const fixtureVersion = "2026-09-29.1";
export const professionalReview = "PENDING";
export const sourceCheckedAt = "2026-09-29";

export interface PeriodCase {
  id: string;
  description: string;
  now: string;
  expected: {
    today: string;
    current: string;
    period: string;
    due: string;
    days: number;
  };
}

