export interface RegimeCase {
  id: string;
  description: string;
  calculation: "MONTHLY" | "ANNUAL";
  rfc: string;
  scalar: string;
  period: string;
  rows: readonly { code: string; since: string | null; endedAt: string | null; active: boolean }[];
  expected: {
    codes: readonly string[];
    track: string | null;
    reason: "ASSISTED_ONLY" | "ENGINE_NOT_IMPLEMENTED" | "NOT_APPLICABLE" | "UNKNOWN_REGIME" | "INCOMPATIBLE_TAXPAYER_TYPE" | "MULTI_REGIME_COMPOSITION_REQUIRED" | null;
  };
}

// Synthetic RFCs encode only the PF/PM shape; they identify no customer.
const pf = "AAAA010101AAA";
const pm = "AAA010101AAA";
const regimeInput = { calculation: "MONTHLY" as const, rfc: pf, period: "2026-08", rows: [] };
const mixedRows = [
  { code: "612", since: null, endedAt: null, active: true },
  { code: "606", since: null, endedAt: null, active: true },
];
const companionRows = [mixedRows[0], { code: "605", since: null, endedAt: null, active: true }];
const historicalRows = [
  { code: "608", since: "2024-01-01T00:00:00Z", endedAt: "2026-01-01T00:00:00Z", active: false },
  { code: "612", since: "2026-01-01T00:00:00Z", endedAt: null, active: true },
];

export const regimeCases: readonly RegimeCase[] = [
  { ...regimeInput, id: "REG-001", description: "General PM monthly engine enabled", rfc: pm, scalar: "601",
    expected: { codes: ["601"], track: "601", reason: null } },
  { ...regimeInput, id: "REG-002", description: "PFAE monthly engine enabled", scalar: "612",
    expected: { codes: ["612"], track: "612", reason: null } },
  { ...regimeInput, id: "REG-003", description: "Rentals monthly engine enabled", scalar: "606",
    expected: { codes: ["606"], track: "606", reason: null } },
  { ...regimeInput, id: "REG-004", description: "Platforms monthly engine enabled", scalar: "625",
    expected: { codes: ["625"], track: "625", reason: null } },
  { ...regimeInput, id: "REG-005", description: "RESICO PF monthly engine enabled", scalar: "626",
    expected: { codes: ["626"], track: "626-PF", reason: null } },
  { ...regimeInput, id: "REG-006", description: "General PM annual engine enabled", calculation: "ANNUAL", rfc: pm, scalar: "601",
    expected: { codes: ["601"], track: "601", reason: null } },
  { ...regimeInput, id: "REG-007", description: "PFAE annual engine enabled", calculation: "ANNUAL", scalar: "612",
    expected: { codes: ["612"], track: "612", reason: null } },
  { ...regimeInput, id: "REG-008", description: "RESICO PM cannot fall through to RESICO PF", rfc: pm, scalar: "626",
    expected: { codes: ["626"], track: "626-PM", reason: "ENGINE_NOT_IMPLEMENTED" } },
  { ...regimeInput, id: "REG-009", description: "Nonprofit PM remains assisted", rfc: pm, scalar: "603",
    expected: { codes: ["603"], track: "603", reason: "ASSISTED_ONLY" } },
  { ...regimeInput, id: "REG-010", description: "No fiscal obligations is not a calculated zero", scalar: "616",
    expected: { codes: ["616"], track: "616", reason: "NOT_APPLICABLE" } },
  { ...regimeInput, id: "REG-011", description: "Unknown regime fails closed", scalar: "999",
    expected: { codes: ["999"], track: null, reason: "UNKNOWN_REGIME" } },
  { ...regimeInput, id: "REG-012", description: "Two monthly engines require explicit composition", scalar: "612", rows: mixedRows,
    expected: { codes: ["612", "606"], track: "612", reason: "MULTI_REGIME_COMPOSITION_REQUIRED" } },
  { ...regimeInput, id: "REG-013", description: "Salary companion does not contaminate the monthly PFAE engine", scalar: "612", rows: companionRows,
    expected: { codes: ["612", "605"], track: "612", reason: null } },
  { ...regimeInput, id: "REG-014", description: "Salary companion still requires annual composition", calculation: "ANNUAL", scalar: "612", rows: companionRows,
    expected: { codes: ["612", "605"], track: "612", reason: "MULTI_REGIME_COMPOSITION_REQUIRED" } },
  { ...regimeInput, id: "REG-015", description: "Historical period uses the old regime, not today's scalar", scalar: "612", period: "2025-08", rows: historicalRows,
    expected: { codes: ["608"], track: "608", reason: "ASSISTED_ONLY" } },
  { ...regimeInput, id: "REG-016", description: "Ended regime is excluded at the half-open boundary", scalar: "612", period: "2026-01", rows: historicalRows,
    expected: { codes: ["612"], track: "612", reason: null } },
  { ...regimeInput, id: "REG-017", description: "PM-only regime cannot calculate for a PF", scalar: "601",
    expected: { codes: ["601"], track: "601", reason: "INCOMPATIBLE_TAXPAYER_TYPE" } },
  { ...regimeInput, id: "REG-018", description: "Annual historical calculation cannot use today's supported regime", calculation: "ANNUAL", scalar: "612", period: "2025-08", rows: historicalRows,
    expected: { codes: ["608"], track: "608", reason: "ASSISTED_ONLY" } },
];
